cd /home/runner/work/friends-main && python3 - <<'PY'
import re, subprocess
branches=['rachel','monica','phoebe','joey','chandler','ross']
commits={}
for b in branches:
    out=subprocess.check_output(['git','log','--reverse','--format=%H%x1f%ci%x1f%B%x1e',f'origin/friend/{b}'],text=True)
    for rec in out.split('\x1e'):
        if not rec.strip(): continue
        sha,ci,body=rec.split('\x1f',2)
        if 'Friend-Message: 1' in body and 'Episode: S05/E25' in body:
            commits.setdefault(sha,(b,ci,body.strip()))
print('total source commits',len(commits))
txt=open('S05/E25.md').read()
trans=set(re.findall(r'Source: friend/\w+ @ ([0-9a-f]{40})',txt))
print('transcribed',len(trans))
for sha in sorted(commits,key=lambda s:(commits[s][1],s)):
    if sha not in trans:
        b,ci,body=commits[sha]
        print('MISSING',sha,b,ci)
        for l in body.splitlines():
            if l.startswith(('Rachel:','Monica:','Phoebe:','Joey:','Chandler:','Ross:')):
                print('   ',l)
PY
